Below is a simple C++ program that computes the nth term of the sequence defined by
a0 = 0, a1 = -1, a2 = -1, and for n >= 3:
a_n = a_{n-1} + a_{n-2} + a_{n-3}.

This uses an iterative (bottom-up) approach (O(n) time, O(1) extra space).

```cpp
#include <iostream>
#include <vector>
#include <limits>

using namespace std;

long long tribonacci(long long n) {
    if (n < 0) throw invalid_argument("n must be non-negative");
    if (n == 0) return 0;
    if (n == 1 || n == 2) return -1;

    long long a = 0;   // a0
    long long b = -1;  // a1
    long long c = -1;  // a2
    long long d = 0;

    for (long long i = 3; i <= n; ++i) {
        d = a + b + c;
        a = b;
        b = c;
        c = d;
    }
    return c;
}

int main() {
    long long n;
    cout << "Enter n (non-negative integer): ";
    if (!(cin >> n)) {
        cerr << "Invalid input\n";
        return 1;
    }
    if (n < 0) {
        cerr << "Please enter a non-negative integer\n";
        return 1;
    }

    try {
        long long result = tribonacci(n);
        cout << "a[" << n << "] = " << result << '\n';
    } catch (const exception &e) {
        cerr << "Error: " << e.what() << '\n';
        return 1;
    }
    return 0;
}
```

