def lowest_common_ancestor(root, p, q):
    """
    Return the lowest common ancestor node of p and q in binary tree rooted at root.
    Returns None if either p or q is not found in the tree.
    """
    # Helper that returns (node, found_count) where node is LCA if found_count == 2
    def helper(node):
        if node is None:
            return (None, 0)
        left_node, left_count = helper(node.left)
        right_node, right_count = helper(node.right)
        total = left_count + right_count + (1 if node is p or node is q else 0)
        # If this node is p or q, and one of the children contains the other, or both children contain p & q,
        # then this node is the LCA.
        if node is p or node is q:
            return (node, total)
        if left_node and right_node:
            # p and q found in different subtrees
            return (node, total)
        if left_node:
            return (left_node, total)
        if right_node:
            return (right_node, total)
        return (None, total)

    node, count = helper(root)
    return node if count == 2 else None
```

2) Highest common ancestor by value (find common ancestors, pick the one with max node.val):
