def ancestors(root, target):
    # returns list of ancestor nodes from root down to target (inclusive), or [] if not found
    path = []
    def dfs(node):
        if node is None:
            return False
        path.append(node)
        if node is target:
            return True
        if dfs(node.left) or dfs(node.right):
            return True
        path.pop()
        return False
    if dfs(root):
        return list(path)
    return []

def highest_common_by_value(root, p, q):
    ap = ancestors(root, p)
    aq = ancestors(root, q)
    if not ap or not aq:
        return None
    # intersect by identity
    s = set(ap)
    common = [node for node in aq if node in s]  # nodes from root..target that are common
    # pick one with max value
    return max(common, key=lambda n: n.val)
```

