using namespace std;

int main() {
    vector<int> A = {4, 2, 3, 2, 8};
    vector<int> B = {3, 2, 2, 10, 4};

    sort(A.begin(), A.end());
    sort(B.begin(), B.end());

    int i = 0, j = 0, n = A.size(), m = B.size();
    while (i < n && j < m) {
        if (A[i] < B[j]) ++i;
        else if (A[i] > B[j]) ++j;
        else {
