1) Unique common elements
```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> intersection_unique(const vector<int>& A, const vector<int>& B) {
    const vector<int> &small = (A.size() < B.size()) ? A : B;
    const vector<int> &large = (A.size() < B.size()) ? B : A;

    unordered_set<int> s(small.begin(), small.end());
    unordered_set<int> out;
    for (int x : large) if (s.count(x)) out.insert(x);

    return vector<int>(out.begin(), out.end()); // order is arbitrary
}
```

2) Intersection with multiplicity
```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> intersection_with_multiplicity(const vector<int>& A, const vector<int>& B) {
    const vector<int> &small = (A.size() < B.size()) ? A : B;
    const vector<int> &large = (A.size() < B.size()) ? B : A;

    unordered_map<int,int> cnt;
    for (int x : small) ++cnt[x];

    vector<int> res;
    for (int x : large) {
        auto it = cnt.find(x);
        if (it != cnt.end() && it->second > 0) {
            res.push_back(x);
            --(it->second);
        }
    }
    return res;
}
```

